<?php
$root=dirname(__DIR__);$version=trim((string)file_get_contents($root.'/VERSION'));$package=$root.'/dist/pkg_xdecaroanalytics_'.$version.'.zip';$feed=$root.'/updates/pkg_xdecaroanalytics.xml';if(!is_file($package)||!is_file($feed)){fwrite(STDERR,"Missing package or update feed.\n");exit(1);} $sha=hash_file('sha256',$package);$xml=file_get_contents($feed);$updated=preg_replace('/<sha256>[a-f0-9]{64}<\/sha256>/','<sha256>'.$sha.'</sha256>',$xml,1,$count);if($updated===null||$count!==1){fwrite(STDERR,"Unable to update SHA-256.\n");exit(1);}file_put_contents($feed,$updated);echo $sha,"\n";
